import{_ as o,a0 as p,w as d,s as r,I as i,x as e,a1 as a,A as t,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Linux 远程连接之 SSH 新手指南 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 远程连接之 SSH 新手指南 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 远程连接之 SSH 新手指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 远程连接之 SSH 新手指南 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20200907 A beginner-s guide to SSH for remote connection on Linux","title":"Linux 远程连接之 SSH 新手指南","tag":"202108","desc":""},"relativePath":"202108/20200907 A beginner-s guide to SSH for remote connection on Linux.md","filePath":"[post].md"}'),h={name:"202108/20200907 A beginner-s guide to SSH for remote connection on Linux.md"};function g(c,s,u,b,k,S){const n=p("Link");return d(),r("div",null,[s[23]||(s[23]=i("h1",{id:"linux-远程连接之-ssh-新手指南",tabindex:"-1"},[e("Linux 远程连接之 SSH 新手指南 "),i("a",{class:"header-anchor",href:"#linux-远程连接之-ssh-新手指南","aria-label":"Permalink to “Linux 远程连接之 SSH 新手指南”"},"​")],-1)),s[24]||(s[24]=i("blockquote",null,[i("p",null,"学会使用安全外壳协议连接远程计算机。")],-1)),s[25]||(s[25]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/28/105409ztj7akfjpcluwjp3.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=e("使用 Linux，你只需要在键盘上输入命令，就可以巧妙地使用计算机（甚至这台计算机可以在世界上任何地方），这正是 Linux 最吸引人的特性之一。有了 OpenSSH，",-1)),a(n,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:t(()=>[...s[0]||(s[0]=[e("POSIX",-1)])]),_:1}),s[2]||(s[2]=e(" 用户就可以在有权限连接的计算机上打开安全外壳协议，然后远程使用。这对于许多 Linux 用户来说可能不过是日常任务，但从没操作过的人可能就会感到很困惑。本文介绍了如何配置两台计算机的 ",-1)),s[3]||(s[3]=i("ruby",null,[e("安全外壳协议"),i("rt",null,"secure shell")],-1)),s[4]||(s[4]=e("（简称 SSH）连接，以及如何在没有密码的情况下安全地从一台计算机连接到另一台计算机。",-1))]),s[26]||(s[26]=l(`<h3 id="相关术语" tabindex="-1">相关术语 <a class="header-anchor" href="#相关术语" aria-label="Permalink to “相关术语”">​</a></h3><p>在讨论多台计算机时，如何将不同计算机彼此区分开可能会让人头疼。IT 社区拥有完善的术语来描述计算机联网的过程。</p><ul><li><ruby>服务<rt>service</rt></ruby>： 服务是指在后台运行的软件，因此它不会局限于仅供安装它的计算机使用。例如，Web 服务器通常托管着 Web 共享 <em>服务</em>。该术语暗含（但非绝对）它是没有图形界面的软件。</li><li><ruby>主机<rt>host</rt></ruby>： 主机可以是任何计算机。在 IT 中，任何计算机都可以称为 <em>主机</em>，因为从技术上讲，任何计算机都可以<ruby>托管<rt>host</rt></ruby>对其他计算机有用的应用程序。你可能不会把自己的笔记本电脑视为 <strong>主机</strong>，但其实上面可能正运行着一些对你、你的手机或其他计算机有用的服务。</li><li><ruby>本地<rt>local</rt></ruby>： 本地计算机是指用户或某些特定软件正在使用的计算机。例如，每台计算机都会把自己称为 <code>localhost</code>。</li><li><ruby>远程<rt>remote</rt></ruby>： 远程计算机是指你既没在其面前，也没有在实际使用的计算机，是真正意义上在 <em>远程</em> 位置的计算机。</li></ul><p>现在术语已经明确好，我们可以开始了。</p><h3 id="在每台主机上激活-ssh" tabindex="-1">在每台主机上激活 SSH <a class="header-anchor" href="#在每台主机上激活-ssh" aria-label="Permalink to “在每台主机上激活 SSH”">​</a></h3><p>要通过 SSH 连接两台计算机，每个主机都必须安装 SSH。SSH 有两个组成部分：本地计算机上使用的用于启动连接的命令，以及用于接收连接请求的 <em>服务器</em>。有些计算机可能已经安装好了 SSH 的一个或两个部分。验证 SSH 是否完全安装的命令因系统而异，因此最简单的验证方法是查阅相关配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file /etc/ssh/ssh_config</span></span>
<span class="line"><span>/etc/ssh/ssh_config: ASCII text</span></span></code></pre></div><p>如果返回 <code>No such file or directory</code> 错误，说明没有安装 SSH 命令。</p><p>SSH 服务的检测与此类似（注意文件名中的 <code>d</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file /etc/ssh/sshd_config</span></span>
<span class="line"><span>/etc/ssh/sshd_config: ASCII text</span></span></code></pre></div><p>根据缺失情况选择安装两个组件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install openssh-clients openssh-server</span></span></code></pre></div><p>在远程计算机上，使用 systemd 命令启用 SSH 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now sshd</span></span></code></pre></div><p>你也可以在 GNOME 上的 <strong>系统设置</strong> 或 macOS 上的 <strong>系统首选项</strong> 中启用 SSH 服务。在 GNOME 桌面上，该设置位于 <strong>共享</strong> 面板中：</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome-activate-remote-login.png" alt="在 GNOME 系统设置中激活 SSH" title="Activate SSH in GNOME System Settings"></p><h3 id="开启安全外壳协议" tabindex="-1">开启安全外壳协议 <a class="header-anchor" href="#开启安全外壳协议" aria-label="Permalink to “开启安全外壳协议”">​</a></h3><p>现在你已经在远程计算机上安装并启用了 SSH，可以尝试使用密码登录作为测试。要访问远程计算机，你需要有用户帐户和密码。</p><p>远程用户不必与本地用户相同。只要拥有相应用户的密码，你就可以在远程机器上以任何用户的身份登录。例如，我在我的工作计算机上的用户是 <code>sethkenlon</code> ，但在我的个人计算机上是 <code>seth</code>。如果我正在使用我的个人计算机（即作为当前的本地计算机），并且想通过 SSH 连接到我的工作计算机，我可以通过将自己标识为 <code>sethkenlon</code> 并使用我的工作密码来实现连接。</p><p>要通过 SSH 连接到远程计算机，你必须知道其 IP 地址或可解析的主机名。在远程计算机上使用 <code>ip</code> 命令可以查看该机器的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip addr show | grep &quot;inet &quot;</span></span>
<span class="line"><span>inet 127.0.0.1/8 scope host lo</span></span>
<span class="line"><span>inet 10.1.1.5/27 brd 10.1.1.31 [...]</span></span></code></pre></div><p>如果远程计算机没有 <code>ip</code> 命令，可以尝试使用 <code>ifconfig</code> 命令（甚至可以试试 Windows 上通用的 <code>ipconfig</code> 命令）。</p>`,22)),i("p",null,[s[6]||(s[6]=l("<code>127.0.0.1</code> 是一个特殊的地址，它实际上是 <code>localhost</code> 的地址。这是一个<ruby>环回<rt>loopback</rt></ruby>地址，系统使用它来找到自己。这在登录远程计算机时并没有什么用，因此在此示例中，远程计算机的正确 IP 地址为 <code>10.1.1.5</code>。在现实生活中，我的本地网络正在使用 <code>10.1.1.0</code> 子网，进而可得知前述正确的 IP 地址。如果远程计算机在不同的网络上，那么 IP 地址几乎可能是任何地址（但绝不会是 <code>127.0.0.1</code>），并且可能需要一些特殊的路由才能通过各种防火墙到达远程。如果你的远程计算机在同一个网络上，但想要访问比自己的网络更远的计算机，请阅读我之前写的关于 ",12)),a(n,{href:"https://opensource.com/article/20/8/open-ports-your-firewall"},{default:t(()=>[...s[5]||(s[5]=[e("在防火墙中打开端口",-1)])]),_:1}),s[7]||(s[7]=e(" 的文章。",-1))]),s[27]||(s[27]=l(`<p>如果你能通过 IP 地址 <em>或</em> 主机名 <code>ping</code> 到远程机器，并且拥有登录帐户，那么就可以通过 SSH 接入远程机器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c1 10.1.1.5</span></span>
<span class="line"><span>PING 10.1.1.5 (10.1.1.5) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 10.1.1.5: icmp_seq=1 ttl=64 time=4.66 ms</span></span>
<span class="line"><span>$ ping -c1 akiton.local</span></span>
<span class="line"><span>PING 10.1.1.5 (10.1.1.5) 56(84) bytes of data.</span></span></code></pre></div><p>至此就成功了一小步。再试试使用 SSH 登录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whoami</span></span>
<span class="line"><span>seth</span></span>
<span class="line"><span>$ ssh sethkenlon@10.1.1.5</span></span>
<span class="line"><span>bash$ whoami</span></span>
<span class="line"><span>sethkenlon</span></span></code></pre></div><p>测试登录有效，下一节会介绍如何激活无密码登录。</p><h3 id="创建-ssh-密钥" tabindex="-1">创建 SSH 密钥 <a class="header-anchor" href="#创建-ssh-密钥" aria-label="Permalink to “创建 SSH 密钥”">​</a></h3><p>要在没有密码的情况下安全地登录到另一台计算机，登录者必须拥有 SSH 密钥。可能你的机器上已经有一个 SSH 密钥，但再多创建一个新密钥也没有什么坏处。SSH 密钥的生命周期是在本地计算机上开始的，它由两部分组成：一个是永远不会与任何人或任何东西共享的私钥，一个是可以复制到任何你想要无密码访问的远程机器上的公钥。</p><p>有的人可能会创建一个 SSH 密钥，并将其用于从远程登录到 GitLab 身份验证的所有操作，但我会选择对不同的任务组使用不同的密钥。例如，我在家里使用一个密钥对本地机器进行身份验证，使用另一个密钥对我维护的 Web 服务器进行身份验证，再一个单独的密钥用于 Git 主机，以及又一个用于我托管的 Git 存储库，等等。在此示例中，我将只创建一个唯一密钥，以在局域网内的计算机上使用。</p><p>使用 <code>ssh-keygen</code> 命令创建新的 SSH 密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-keygen -t ed25519 -f ~/.ssh/lan</span></span></code></pre></div><p><code>-t</code> 选项代表 <em>类型</em> ，上述代码设置了一个高于默认值的密钥加密级别。<code>-f</code> 选项代表 <em>文件</em>，指定了密钥的文件名和位置。运行此命令后会生成一个名为 <code>lan</code> 的 SSH 私钥和一个名为 <code>lan.pub</code> 的 SSH 公钥。</p><p>使用 <code>ssh-copy-id</code> 命令把公钥发送到远程机器上，在此之前要先确保具有远程计算机的 SSH 访问权限。如果你无法使用密码登录远程主机，也就无法设置无密码登录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-copy-id -i ~/.ssh/lan.pub sethkenlon@10.1.1.5</span></span></code></pre></div><p>过程中系统会提示你输入远程主机上的登录密码。</p><p>操作成功后，使用 <code>-i</code> 选项将 SSH 命令指向对应的密钥（在本例中为 <code>lan</code>）再次尝试登录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -i ~/.ssh/lan sethkenlon@10.1.1.5</span></span>
<span class="line"><span>bash$ whoami</span></span>
<span class="line"><span>sethkenlon</span></span></code></pre></div><p>对局域网上的所有计算机重复此过程，你就将能够无密码访问这个局域网上的每台主机。实际上，一旦你设置了无密码认证，你就可以编辑 <code>/etc/ssh/sshd_config</code> 文件来禁止密码认证。这有助于防止其他人使用 SSH 对计算机进行身份验证，除非他们拥有你的私钥。要想达到这个效果，可以在有 <code>sudo</code> 权限的文本编辑器中打开 <code>/etc/ssh/sshd_config</code> 并搜索字符串 <code>PasswordAuthentication</code>，将默认行更改为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PasswordAuthentication no</span></span></code></pre></div><p>保存并重启 SSH 服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart sshd &amp;amp;&amp;amp; echo &quot;OK&quot;</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="日常使用-ssh" tabindex="-1">日常使用 SSH <a class="header-anchor" href="#日常使用-ssh" aria-label="Permalink to “日常使用 SSH”">​</a></h3><p>OpenSSH 改变了人们对操作计算机的看法，使用户不再被束缚在面前的计算机上。使用 SSH，你可以访问家中的任何计算机，或者拥有帐户的服务器，甚至是移动和物联网设备。充分利用 SSH 也意味着解锁 Linux 终端的更多用途。如果你还没有使用过 SSH，请试一下它吧。试着适应 SSH，创建一些适当的密钥，以此更安全地使用计算机，打破必须与计算机面对面的局限性。</p><hr>`,23)),i("p",null,[s[9]||(s[9]=e("via: ",-1)),a(n,{href:"https://opensource.com/article/20/9/ssh"},{default:t(()=>[...s[8]||(s[8]=[e("https://opensource.com/article/20/9/ssh",-1)])]),_:1})]),i("p",null,[s[14]||(s[14]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[10]||(s[10]=[e("Seth Kenlon",-1)])]),_:1}),s[15]||(s[15]=e(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[11]||(s[11]=[e("lujun9972",-1)])]),_:1}),s[16]||(s[16]=e(" 译者：",-1)),a(n,{href:"https://github.com/unigeorge"},{default:t(()=>[...s[12]||(s[12]=[e("unigeorge",-1)])]),_:1}),s[17]||(s[17]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[20]||(s[20]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[e("LCTT",-1)])]),_:1}),s[21]||(s[21]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[e("Linux中国",-1)])]),_:1}),s[22]||(s[22]=e(" 荣誉推出",-1))])])}const x=o(h,[["render",g]]);export{y as __pageData,x as default};
